from collections.abc import Awaitable, Callable


async def run_tasks(
    tasks: list[Callable[[], Awaitable[None]]],
    max_concurrent: int,
) -> None:
    """Run ``tasks`` with at most ``max_concurrent`` of them running at once.

    Every element of ``tasks`` is a zero-argument callable returning an
    awaitable (normally a coroutine object). The tasks are scheduled and run
    concurrently, bounded by ``max_concurrent``.

    If the coroutine is cancelled (e.g. a Ctrl-C delivered through
    ``asyncio.run``), unfinished tasks are cancelled exactly once and
    ``run_tasks`` waits for them to finish their cleanup code before the
    cancellation is re-raised.
    """
    if max_concurrent <= 0:
        raise ValueError("max_concurrent must be greater than 0")

    semaphore = asyncio.Semaphore(max_concurrent)

    async def run_one(task_fn: Callable[[], Awaitable[None]]) -> None:
        async with semaphore:
            await task_fn()

    jobs = [asyncio.create_task(run_one(task_fn)) for task_fn in tasks]
    pending = set(jobs)

    try:
        while pending:
            _, pending = await asyncio.wait(
                pending,
                return_when=asyncio.FIRST_COMPLETED,
            )
    except asyncio.CancelledError:
        # We are being cancelled. Send one cancellation to every job that has
        # not finished yet so its finally/cleanup code can still execute.
        for job in jobs:
            if not job.done():
                job.cancel()

        # Wait for all jobs to actually finish their cleanup, ignoring any
        # further cancellation requests that arrive while we are waiting.
        while True:
            if all(job.done() for job in jobs):
                break
            try:
                await asyncio.wait(jobs)
            except asyncio.CancelledError:
                continue

        raise

    # Normal completion: if any task raised, re-raise the first exception.
    for job in jobs:
        if job.cancelled():
            continue
        error = job.exception()
        if error is not None:
            raise error
