    try:
        await run_tasks(
            [lambda: job("a"), lambda: job("b"), lambda: job("c")],
            2,
        )
        print("RUN_TASKS RETURNED NORMALLY", flush=True)
    except asyncio.CancelledError:
        print("MAIN CAUGHT CANCELLED", flush=True)
        raise
    except KeyboardInterrupt:
        print("MAIN CAUGHT KEYBOARDINTERRUPT", flush=True)
    print("MAIN END", flush=True)


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except BaseException as e:
        print("OUTER CAUGHT:", type(e).__name__, flush=True)
        raise
